// 24-S5 acceptance: the puzzle actions for collaborators, as the session's
// account, against PostgreSQL (a throwaway schema). The session gate is the
// real one; only Better Auth's session read is stubbed. A collaborator opens
// and duplicates the shared puzzle; deleting, visibility and membership stay
// with the owner. Do not edit this file to match an implementation.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import type { Prisma } from '@prisma/client';
import { createGrid, withLetter } from '@/engine/grid';
import { serializeGrid } from '@/lib/puzzle-storage';
import { createTestDatabase, type TestDatabase } from '@/test-support/database';

const holder = vi.hoisted(() => ({ client: undefined as unknown, session: null as unknown }));
vi.mock('@/lib/prisma', () => ({
  prisma: new Proxy({}, {
    get(_target, key) {
      const client = holder.client as Record<PropertyKey, unknown>;
      const value = Reflect.get(client, key);
      return typeof value === 'function' ? value.bind(client) : value;
    },
  }),
}));
vi.mock('@/lib/auth', () => ({ auth: { api: { getSession: async () => holder.session } } }));
vi.mock('next/headers', () => ({ headers: async () => new Headers() }));
vi.mock('next/cache', () => ({ revalidatePath: () => undefined }));

import {
  addCollaborator, catchUpOperations, claimInvitations, commitOperation, deletePuzzle, duplicatePuzzle,
  listCollaborators, loadPuzzle, removeCollaborator, revokeInvitation, setPuzzleVisibility,
} from './actions';

const USERS = {
  adam: { id: 'adam', email: 'adam@actions5.example.test', displayName: 'Adam' },
  jay: { id: 'jay', email: 'jay@actions5.example.test', displayName: 'Jay' },
  eve: { id: 'eve', email: 'eve@actions5.example.test', displayName: 'Eve' },
};
type Name = keyof typeof USERS;
const as = (name: Name, email = USERS[name].email) => {
  holder.session = { user: { ...USERS[name], email }, session: {} };
};

let db: TestDatabase;
beforeAll(async () => {
  db = await createTestDatabase();
  holder.client = db.client;
  await db.client.user.createMany({ data: Object.values(USERS).map((user) => ({ ...user, name: user.displayName })) });
}, 60_000);
afterAll(async () => { await db?.drop(); });
beforeEach(() => as('adam'));

const grid = serializeGrid(withLetter(createGrid({ cols: 3, rows: 3 }), { col: 0, row: 0 }, 'Q'));
async function seed(options: { collaborators?: Name[]; publishedAt?: Date; invitations?: string[] } = {}) {
  const id = (await db.client.puzzle.create({
    data: {
      builderId: 'adam', title: 'Shared', grid: grid as unknown as Prisma.InputJsonValue, hints: {},
      publishedAt: options.publishedAt ?? null,
    },
  })).id;
  for (const name of options.collaborators ?? ['jay']) await db.client.puzzleCollaborator.create({ data: { puzzleId: id, userId: name } });
  for (const email of options.invitations ?? []) {
    await db.client.puzzleInvitation.create({ data: { puzzleId: id, email, expiresAt: new Date(Date.now() + 86_400_000) } });
  }
  return id;
}
const row = (id: string) => db.client.puzzle.findUnique({ where: { id } });
const memberIds = async (puzzleId: string) =>
  (await db.client.puzzleCollaborator.findMany({ where: { puzzleId } })).map((member) => member.userId).sort();

describe('24-S5-7 the actions for a collaborator, as the session account', () => {
  it('loadPuzzle opens the shared puzzle for the owner and a collaborator, and nobody else', async () => {
    const id = await seed();
    expect(await loadPuzzle(id)).toMatchObject({ id, title: 'Shared', isOwner: true });
    as('jay');
    expect(await loadPuzzle(id)).toMatchObject({ id, title: 'Shared', isOwner: false, version: 0, resetEpoch: 0 });
    as('eve');
    expect(await loadPuzzle(id)).toBeNull();
    await db.client.puzzleCollaborator.deleteMany({ where: { puzzleId: id, userId: 'jay' } });
    as('jay');
    expect(await loadPuzzle(id)).toBeNull();
  });

  it('a collaborator duplicates the shared puzzle into a copy of their own, with nobody else on it', async () => {
    const id = await seed({ collaborators: ['jay', 'eve'], invitations: ['pending@example.test'] });
    const before = await row(id);
    as('jay');
    const copy = await duplicatePuzzle(id);
    const made = await row(copy.id);
    expect(made).toMatchObject({ builderId: 'jay', title: 'Shared (copy)', grid, publishedAt: null });
    expect(await memberIds(copy.id)).toEqual([]);
    expect(await db.client.puzzleInvitation.count({ where: { puzzleId: copy.id } })).toBe(0);
    expect(await row(id)).toEqual(before);
    expect(await memberIds(id)).toEqual(['eve', 'jay']);
    // A stranger can't.
    await db.client.puzzleCollaborator.deleteMany({ where: { puzzleId: id, userId: 'eve' } });
    as('eve');
    await expect(duplicatePuzzle(id)).rejects.toThrow();
  });

  it('a collaborator can’t delete the puzzle or change its visibility; the owner’s delete takes the membership with it', async () => {
    const id = await seed({ invitations: ['pending@example.test'] });
    const published = await seed({ publishedAt: new Date('2026-11-01T00:00:00Z') });
    const before = await row(id);
    const beforePublished = await row(published);
    as('jay');
    await expect(deletePuzzle(id)).rejects.toThrow();
    await expect(setPuzzleVisibility(published, 'public')).rejects.toThrow();
    expect(await row(id)).toEqual(before);
    expect(await row(published)).toEqual(beforePublished);

    as('adam');
    await deletePuzzle(id);
    expect(await row(id)).toBeNull();
    expect(await db.client.puzzleCollaborator.count({ where: { puzzleId: id } })).toBe(0);
    expect(await db.client.puzzleInvitation.count({ where: { puzzleId: id } })).toBe(0);
    expect(await setPuzzleVisibility(published, 'public')).toEqual({ visibility: 'public' });
  });

  it('the membership actions act for the session’s account, and only the owner’s', async () => {
    const id = await seed({ collaborators: [] });
    as('jay');
    for (const result of [
      await addCollaborator({ puzzleId: id, email: USERS.eve.email, ownerId: 'adam', userId: 'adam' }),
      await listCollaborators({ puzzleId: id, ownerId: 'adam' }),
      await removeCollaborator({ puzzleId: id, userId: 'eve', ownerId: 'adam' }),
      await revokeInvitation({ puzzleId: id, email: 'x@example.test', ownerId: 'adam' }),
    ]) expect(result).toEqual({ status: 'not-found' });
    expect(await memberIds(id)).toEqual([]);

    as('adam');
    expect(await addCollaborator({ puzzleId: id, email: USERS.jay.email.toUpperCase(), ownerId: 'eve' })).toEqual({ status: 'added', userId: 'jay', username: 'Jay' });
    expect(await addCollaborator({ puzzleId: id, email: 'newcomer@example.test' })).toMatchObject({ status: 'invited', email: 'newcomer@example.test' });
    expect(await listCollaborators({ puzzleId: id })).toMatchObject({
      status: 'ok', collaborators: [{ userId: 'jay', username: 'Jay' }], invitations: [{ email: 'newcomer@example.test' }],
    });
    as('jay');
    expect(await addCollaborator({ puzzleId: id, email: 'third@example.test' })).toEqual({ status: 'not-found' });
    as('adam');
    expect(await revokeInvitation({ puzzleId: id, email: 'newcomer@example.test' })).toEqual({ status: 'revoked' });
    expect(await removeCollaborator({ puzzleId: id, userId: 'jay' })).toEqual({ status: 'removed' });
    expect(await memberIds(id)).toEqual([]);
  });

  it('claimInvitations claims by the session’s current email, whatever the input', async () => {
    const id = await seed({ collaborators: [] });
    await addCollaborator({ puzzleId: id, email: 'eve-new@example.test' });
    as('jay');
    // Any input is ignored: the session's email decides.
    await (claimInvitations as (input?: unknown) => Promise<unknown>)({ email: 'eve-new@example.test' });
    expect(await memberIds(id)).toEqual([]);
    as('eve', 'Eve-New@Example.test');
    await claimInvitations();
    expect(await memberIds(id)).toEqual(['eve']);
    expect(await loadPuzzle(id)).toMatchObject({ id, isOwner: false });
  });

  it('commitOperation and catchUpOperations serve a collaborator, and refuse a stranger', async () => {
    const id = await seed();
    as('jay');
    const op = { opId: randomUUID(), puzzleId: id, clientId: 'tab', epoch: 0, baseVersion: 0, kind: 'title', title: 'By Jay' };
    expect(await commitOperation(op)).toEqual({ status: 'accepted', opId: op.opId, version: 1 });
    expect(await catchUpOperations({ puzzleId: id, since: 0 })).toEqual({ status: 'ops', ops: [{ ...op, version: 1 }] });
    as('eve');
    expect(await commitOperation({ ...op, opId: randomUUID(), baseVersion: 1, title: 'By Eve' })).toEqual({ status: 'not-found' });
    expect(await catchUpOperations({ puzzleId: id, since: 0 })).toEqual({ status: 'not-found' });
    expect((await row(id))?.title).toBe('By Jay');
  });
});
